"""Generate out/w2-B.workflow.json for Brief B (on top of Brief A)."""
import json, sys

BASE = "https://freya-bank-mock.freyavoice.workers.dev/v1"
BLOCK_URL = "http://127.0.0.1:9/blocked"

HDR = {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}}


def api_tool(name, desc, fields, required, post="", pre="", mapping=None, retries=0):
    props = {"customer_id": {"type": "string", "default": "{{customer_id}}"}}
    props.update(fields)
    t = {
        "type": "function",
        "config": {"timeoutMs": 12000, "maxRetries": retries},
        "function": {
            "name": name,
            "handler": "__function__:api_call",
            "description": desc,
            "parameters": {
                "type": "object",
                "properties": {
                    "url": {"type": "string", "default": f"{BASE}/{name}"},
                    "method": {"type": "string", "default": "POST"},
                    "headers": HDR,
                    "body": {"type": "object", "properties": props, "required": required},
                },
            },
        },
    }
    if pre:
        t["pre_process_code"] = pre
    if post:
        t["post_process_code"] = post
    if mapping:
        t["response_mapping"] = mapping
    return t


