DATE_LIB = r'''
import json, re, datetime
HOL = set(['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01'])
WD = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
MO = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']
ONE = datetime.timedelta(days=1)
def isbd(d):
    return d.weekday() < 5 and d.isoformat() not in HOL
def say(d):
    return WD[d.weekday()] + ' ' + str(d.day) + ' ' + MO[d.month - 1] + ' ' + str(d.year)
def lab(d):
    return say(d) + ' (' + d.isoformat() + ')'
def money(x):
    try:
        x = float(x)
    except Exception:
        return str(x)
    if abs(x - round(x)) < 0.005:
        return str(int(round(x)))
    return '%.2f' % x
today = None
hh, mi = 12, 0
try:
    m = re.match(r'\s*(\d{4}-\d{2}-\d{2})(?:[T ](\d{1,2}):(\d{2}))?', str(vars.get('now') or ''))
    today = datetime.date.fromisoformat(m.group(1))
    if m.group(2):
        hh, mi = int(m.group(2)), int(m.group(3))
except Exception:
    today = datetime.date.today()
def nth_bd(n):
    d = today
    c = 0
    while c < n:
        d = d + ONE
        if isbd(d):
            c += 1
    return d
monday = today - datetime.timedelta(days=today.weekday())
def last_bd_of_week(mon):
    d = mon + datetime.timedelta(days=4)
    while d >= mon and not isbd(d):
        d = d - ONE
    return d if d >= mon else None
lb_this = last_bd_of_week(monday)
if lb_this is None or lb_this <= today:
    att1 = last_bd_of_week(monday + datetime.timedelta(days=7))
    att1_note = 'last business day of NEXT week (today is the last business day of this week or later)'
else:
    att1 = lb_this
    att1_note = 'last business day of this week'
'''

