        if isinstance(v, dict) and isinstance(v.get('products'), list):
            v = v.get('products')
        if isinstance(v, list) and v:
            return v
    # flattened keys such as x.products.0.product_id
    rows = dict()
    for k, val in list(vars.items()):
        mm = re.search(r'products\.(\d+)\.(\w+)$', str(k))
        if mm:
            rows.setdefault(int(mm.group(1)), dict())[mm.group(2)] = val
