        cal.append('- ' + lab(d) + tag + ': ' + kind)
        d = d + ONE
    wk = []
    for j in range(7):
        t = monday + datetime.timedelta(days=j)
        n = t + datetime.timedelta(days=7)
        wk.append('- "this ' + WD[j] + '" = ' + lab(t) + ('  (already past)' if t < today else '') + ';  "next ' + WD[j] + '" = ' + lab(n))
    rules['bdays'] = [x.split(' (')[1][:10] for x in cal if x.endswith('business day')]
    vars['product_rules'] = json.dumps(rules)
    vars['products_facts'] = '\n\n'.join(facts)
    vars['calendar_text'] = '\n'.join(cal)
    vars['weekday_text'] = '\n'.join(wk)
    vars['attempt1_text'] = (lab(att1) if att1 else '') + ' = ' + att1_note
    vars['product_count'] = str(len(prods))
