    t = str(vars.get('title') or '') + ' ' + str(vars.get('last_name') or '')
    vars['debt_opening'] = 'Thank you, ' + t.strip() + ', you are verified. I am calling from the Freya Bank collections team about a late payment. ' + ' '.join(opening) + ' ' + q
    vars['acct_state'] = 'ok'
except Exception as e:
