    vars['acct_error'] = str(e)[:200]
    vars['products_facts'] = 'Account details are not available.'
    vars['calendar_text'] = ''
    vars['weekday_text'] = ''
    vars['attempt1_text'] = ''
    vars['product_count'] = '0'
    vars['debt_opening'] = ''
    vars['product_rules'] = ''
