                        b['outcome'] = 'no_promise'
                        b['reason'] = first[0]
        if b.get('outcome') in ('promise', 'paid'):
            b.pop('reason', None)
except Exception:
    pass
'''

CLOSE_POST = post_hook(r'''
    if str(d.get('ok')).lower() == 'true':
        d['what_to_do_next'] = 'The call is closed. Say nothing more.'
    else:
        d['what_to_do_next'] = 'close_call was NOT accepted (' + str(d.get('error') or 'error') + '). Fix the outcome or reason and call close_call again.'
''')

# ---------------------------------------------------------------- tools
CLOSE_DESC = ("Record how the call ended. ALWAYS the last tool call. CALL it right after you said thank you and goodbye. "
              "Outcomes and reasons: promise (no reason): at least one promise recorded. paid (no reason): customer already paid. "
              "transferred: reason restructuring, human or support. no_promise: reason refused, hardship, dispute or service_error. "
              "not_verified: reason failed (three wrong answers) or declined (would not answer). "
              "not_reached: reason callback, no_callback, wrong_number, deceased or unclear.")


def close_tool(outcomes, reasons):
    return api_tool(
        "close_call", CLOSE_DESC,
        {
            "outcome": {"type": "string", "enum": outcomes, "default": "{{outcome}}",
                        "description": "One of: " + ", ".join(outcomes)},
            "reason": {"type": "string", "enum": reasons, "default": "{{reason}}",
                       "description": "Reason for the outcome. One of: " + ", ".join(reasons) + ". Leave out for promise and paid."},
        },
        ["outcome"], pre=CLOSE_PRE, post=CLOSE_POST)


ALL_OUTCOMES = ["promise", "paid", "transferred", "no_promise", "not_verified", "not_reached"]
ALL_REASONS = ["refused", "hardship", "dispute", "service_error", "restructuring", "human", "support",
               "failed", "declined", "callback", "no_callback", "wrong_number", "deceased", "unclear"]


def transfer_tool(queues, desc):
    return api_tool(
        "transfer_to_agent", desc,
        {"queue": {"type": "string", "enum": queues, "default": "{{queue}}",
                   "description": "Queue. One of: " + ", ".join(queues) + "."}},
        ["queue"], pre=TRANSFER_PRE, post=TRANSFER_POST)


verify_tool = api_tool(
    "verify_identity",
    "Check ONE security answer. CALL it every time the customer gives a date of birth or the last four phone digits, one call per answer.",
    {
        "field": {"type": "string", "enum": ["date_of_birth", "phone_last4"], "default": "{{field}}",
                  "description": "date_of_birth or phone_last4."},
        "answer": {"type": "string", "default": "{{answer}}",
                   "description": "date_of_birth: YYYY-MM-DD, converted from what the customer said (a date said only in numbers is day, then month, then year). phone_last4: exactly four digits."},
    },
    ["field", "answer"], post=VERIFY_POST)

callback_tool = api_tool(
    "schedule_callback",
    "Book a callback for the customer. CALL it when the person on the line gives a day and time inside the allowed callback window.",
    {
        "date": {"type": "string", "default": "{{date}}", "description": "YYYY-MM-DD"},
        "time": {"type": "string", "default": "{{time}}", "description": "HH:MM, 24 hour"},
    },
    ["date", "time"], pre=CB_PRE, post=CB_POST)

promise_tool = api_tool(
    "create_promise",
    "Record ONE payment promise for ONE product. CALL it only after the customer said a clear yes to the read-back. One call per product.",
    {
        "product_id": {"type": "string", "default": "{{product_id}}",
                       "description": "The exact product_id from the product list, for example p1."},
        "amount": {"type": "number", "default": "{{amount}}", "description": "Agreed amount, a number."},
        "date": {"type": "string", "default": "{{date}}", "description": "Agreed payment date, YYYY-MM-DD."},
    },
    ["product_id", "amount", "date"], pre=CP_PRE, post=CP_POST)

note_tool = api_tool(
    "add_note",
    "Record why ONE product ends without a promise. CALL it once per product without a promise, just before closing. Never on a transfer.",
    {
        "product_id": {"type": "string", "default": "{{product_id}}",
                       "description": "The exact product_id from the product list."},
        "reason": {"type": "string", "enum": ["refused", "hardship", "dispute", "paid", "service_error"],
                   "default": "{{reason}}", "description": "One of: refused, hardship, dispute, paid, service_error."},
    },
    ["product_id", "reason"], pre=NOTE_PRE, post=NOTE_POST)


def close_route(target="hang_up"):
    return {"target_node": target, "description": "The call was closed",
            "condition": {"logic": "or", "conditions": [
                {"variable": "close_call_response.data.ok", "operator": "equals", "operand": "true"},
                {"variable": "close_call_response.data.ok", "operator": "equals", "operand": "True"}]}}


COMMON = ("After every tool result, speak to the customer or call the next tool. Never end a turn with nothing. "
          "Call one tool per message. When a tool result contains what_to_do_next, follow it. "
          "When a rule says to use a tool, call the tool: saying it is not enough. "
          "Before calling close_call, thank the customer and say goodbye in the same message.\n\n")

SYSTEM = """You are Freya Bank's digital assistant on an outbound phone call. Freya Bank is fictional. Speak English. Keep every turn to one to three short sentences. Ask one question at a time.
The customer is {{title}} {{first_name}} {{last_name}}. Address them as {{title}} {{last_name}}.
Today and now: {{now}} (use this, never your own clock).
General rules for the whole call:
- If asked whether you are a robot or an AI: say you are Freya Bank's digital assistant, then continue.
- If asked "is this a scam?": say they can verify this call by phoning Freya Bank's customer service number, then continue.
- If asked something you cannot answer from the information you have: say you do not have that information. Never invent figures, dates or reasons.
- Never offer a discount, a waiver, an instalment plan or any term that is not in your instructions.
- Never say something is recorded, booked or transferred unless the tool result says ok true.
- If a tool fails, say so honestly."""

# ---------------------------------------------------------------- nodes
OPENING_TASK = COMMON + """You are at the start of the call. Your opening line already said you are Freya Bank's digital assistant, that the call is recorded, and asked "Am I speaking with {{title}} {{last_name}}?".
NEVER say "collections", "debt", "payment", "late", an amount or any product here, to anyone, even if asked. If asked why you call, say it is a personal matter for {{title}} {{last_name}}.

WHO IS ON THE LINE
- Only "yes", "that's me", "speaking" or the customer's own name counts as confirmation. "Hello", "go ahead", "who is this" do not.
- If it is unclear, answer any question first (robot, scam, who is calling), then ask once more: "Am I speaking with {{title}} {{last_name}}?". If after this second ask it is still not clear, thank them, say goodbye and call close_call with outcome not_reached, reason unclear.
- If the person wants a human: ask once whether you can help first. If they insist, call transfer_to_agent with queue general, then close_call with outcome transferred, reason human.
- If the customer (confirmed) says they do not want to talk: handled later, not here.

SOMEONE ELSE ANSWERS (a relative, a colleague, anyone who is not {{title}} {{last_name}})
- Say nothing about why you call. Do not ask them any security question and tell them nothing about any account, even if they offer to pay.
- Ask when {{title}} {{last_name}} can be reached.
- {{callback_window}}
- When they give a day and time inside the window: call schedule_callback with date YYYY-MM-DD and time HH:MM, then thank them, say goodbye and call close_call with outcome not_reached, reason callback.
- If the day or time is outside the window: ask ONCE for another time inside the window (say which times are possible). If the second answer is also outside, or they cannot say: do not schedule; thank them, say goodbye and call close_call with outcome not_reached, reason no_callback.
- If they say the number does not belong to {{title}} {{last_name}} (wrong number): apologise, say goodbye and call close_call with outcome not_reached, reason wrong_number.
- If they say {{title}} {{last_name}} has died: say exactly "I am sorry for your loss.", ask nothing else, say goodbye and call close_call with outcome not_reached, reason deceased."""

IDENTITY_TASK = COMMON + """The person confirmed they are {{title}} {{last_name}}. Now run the security check. Do NOT say "collections", "debt", "payment", the product or any amount before both answers are verified.

SECURITY QUESTIONS, one at a time:
1. Ask for their date of birth. Call verify_identity with field date_of_birth and the answer as YYYY-MM-DD, whatever way they said it. A date said only in numbers is day, then month, then year (so 03/04/1985 is 1985-04-03).
2. When the date of birth is verified, ask for the last four digits of the phone number on file. Call verify_identity with field phone_last4 and the four digits.
- A wrong answer may be asked again. Three wrong answers in total end the check (the tool result tells you).
- If the result has the hint day_month_swapped: ask them to say the month as a word. That retry is not a wrong answer.

IF THEY DO NOT ANSWER
- If they decline to answer, or ask what the call is about instead of answering: the first time, explain once that these questions protect their account, and ask the question again. The second time (a second refusal or a second such question): thank them, say goodbye and call close_call with outcome not_verified, reason declined.
- If they say twice that they do not want to talk: thank them, say goodbye, close_call with outcome not_verified, reason declined.
- If they want a human: ask once whether you can help first. If they insist, call transfer_to_agent with queue general, then close_call with outcome transferred, reason human.
- After three wrong answers: do not say anything about the account. Tell them to use the Freya Bank mobile app or a branch, say goodbye and call close_call with outcome not_verified, reason failed."""

NEGOTIATE_TASK = COMMON + """The customer {{title}} {{last_name}} is verified. You already told them every late product and asked whether they can pay today. You are from the collections team. Today is {{today_text}}.

PRODUCTS (in this order; product_id must be copied exactly):
{{products_facts}}

=== HOW TO GET PROMISES ===
Number of products: {{product_count}}. Handle the products in the order above, one at a time. One promise per product at most.
A. The first question (already asked) was whether they can pay (all of it) today. If yes: each product's full past-due amount, date today. Go to READ-BACK.
   Do not ask about "today" again for each product.
B. Otherwise, for the current product:
   - If the customer names a date or an amount, that is NEVER a refusal: check it with the DATE and AMOUNT rules.
   - A plain no, "I can't", or a non-answer, with no date and no amount, is a FLAT REFUSAL and uses one persuasion attempt of THIS product. (For the very first product, the "no" to paying today already counts as a flat refusal: make attempt 1.)
   - Attempt 1: propose the full past-due amount (or the floor if they already said the full amount is too much) on the attempt-1 date of that product.
   - Attempt 2 (late band only): propose the floor amount on that product's deadline.
   - When the attempts of a product are used up: stop, do not repeat an offer already refused. That product ends without a promise (note reason refused). Move to the next product, starting at attempt 1.
   - Never ask "how much can you pay?". You propose every amount. Ask for the full past-due amount first.
AMOUNT rules (per product):
   - From the floor up to the full amount, both included: accept it.
   - "The full amount is too much": offer the floor once, and say the rest stays overdue. If they refuse the floor: flat refusal (uses an attempt).
   - Below the floor: say it cannot be recorded and offer the floor once. If they do not accept: flat refusal.
DATE rules (per product, use ONLY the calendar below, never compute dates yourself):
   - The date must be today or later, a business day, and not after that product's deadline.
   - Weekend or bank holiday not after the deadline: offer the next business day.
   - After the deadline: say the latest date you can record is the deadline (say it) and offer it. If they refuse the deadline: flat refusal.
   - Vague ("next week", "end of the month", "when my salary comes"): ask once for the exact day. If they still give none, propose the deadline.
   - "next <weekday>" and "this <weekday>": use the weekday table below exactly.
   - If they give ONE date for all products and it is after one product's deadline: that product gets its own deadline (say so in the read-back), the others keep the named date.
   - If an amount is given with no date, ask on which day they will pay it.

=== READ-BACK AND RECORDING ===
- When every product has either an agreed amount and date or has ended without a promise, read ALL agreed promises back together (product name, amount, date in words) and ask "Do you confirm?". Only after a clear yes, call create_promise once per agreed product, one call per message, in product order.
- If they change a date or an amount at the read-back, check it again with the rules and read back again.
- Say a promise is recorded ONLY after create_promise returned ok true. If it failed, call it once more. If it fails twice, tell the customer you could not record it, and that product gets a note with reason service_error.
- After the promises are recorded say exactly: "You will receive a text message confirming this promise."
- A recorded promise cannot be changed or cancelled in this call: say they can change it in the mobile app.

=== OTHER SITUATIONS ===
- "I already paid" (this past-due amount, for a product): say payments can take one business day to appear. No promise for that product; its note reason is paid. Continue with the other products.
- "This is not mine" / "I never had this product" / "it was closed or paid off in the past": do not argue, no promise for that product; its note reason is dispute. Continue with the other products.
- Illness, a death in the family or job loss: say one short sentence of sympathy, make NO persuasion attempt, and offer to connect them with the customer support team. If they accept: call transfer_to_agent with queue support, then close transferred / support. If they decline: the products without a promise get the note reason hardship. If they still name a date or amount themselves, record that promise with the normal rules.
- A new payment plan or lower instalments: describe no plan. Call transfer_to_agent with queue restructuring, then close transferred / restructuring. Promises agreed but not yet recorded are NOT recorded.
- A human: ask once whether you can help first. If they insist: transfer_to_agent queue general, then close transferred / human.
- If they say twice that they do not want to talk: the products without a promise get note reason refused, then close.

=== NOTES (add_note) ===
- On ANY transfer (restructuring, support, human): add NO notes at all, before or after it.
- Otherwise, just before closing, call add_note once for EACH product that ends without a recorded promise, with its reason: refused, hardship, dispute, paid or service_error. This applies also when no product gets a promise.

=== CLOSING ===
Thank the customer, say goodbye, then call close_call:
- at least one promise recorded: outcome promise (unless the call was transferred).
- transferred: outcome transferred with the reason of the transfer (restructuring, human or support), even if a promise was recorded before.
- no promise: if every product was noted paid: outcome paid. Otherwise outcome no_promise with the reason of the first product (in list order) whose note is not paid.

=== CALENDAR (business days only are allowed) ===
{{calendar_text}}

Weekday table:
{{weekday_text}}
Attempt-1 date rule: {{attempt1_text}} (never after the product's deadline)."""

ACCOUNT_ERROR_TASK = COMMON + """The customer is verified, but the account details could not be loaded. Say you are sorry, you cannot access the account details right now, and that the bank will contact them again. Do not state any amount. Thank them, say goodbye and call close_call with outcome no_promise and reason service_error."""


def conv(name, task, tools, transitions, on_enter=None, extraction=None, turns=50, first_only=False):
    n = {"name": name, "node_type": "conversation", "task_message": task, "tools": tools,
         "transitions": transitions, "max_node_turns": turns}
    if on_enter:
        n["on_enter"] = on_enter
    if extraction:
        n["extraction_schema"] = extraction
    if first_only:
        n["on_enter_first_entry_only"] = True
    return n


def code_node(name, code, nxt, extra_trans=None):
    trs = list(extra_trans or []) + [{"target_node": nxt, "description": "always", "condition": {"operator": "always"}}]
    return {
        "name": name, "node_type": "code", "passthrough": True, "passthrough_default_transition": nxt,
        "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True,
        "pre_actions": [{"type": "function", "function": {
            "name": "code_exec", "handler": "__function__:code_exec",
            "parameters": {"type": "object", "properties": {
                "code": {"type": "string", "default": code}, "timeout_ms": {"type": "number", "default": 10000}}}}}],
        "transitions": trs,
    }


nodes = {}
nodes["setup"] = code_node("setup", SETUP_CODE, "opening")

nodes["opening"] = conv(
    "opening", OPENING_TASK,
    [callback_tool, transfer_tool(["general"], "Hand the call to a person. CALL it only when the person insists on a human after you asked once whether you can help. Queue general."),
     close_tool(["transferred", "not_reached"], ["human", "callback", "no_callback", "wrong_number", "deceased", "unclear"])],
    [close_route(),
     {"target_node": "identity", "description": "The customer confirmed who they are",
      "condition": {"logic": "or", "conditions": [{"variable": "party", "operator": "equals", "operand": "customer"}]}}],
    on_enter={"type": "tts", "text": "Hello, I am Freya Bank's digital assistant, and this call is recorded. Am I speaking with {{title}} {{last_name}}?"},
    first_only=True,
    extraction=[{
        "name": "party", "type": "string", "enum_values": ["customer", "other_person", "unknown"],
        "description": ("Who is on the line. 'customer' ONLY if, in answer to 'Am I speaking with <title> <last name>?', the speaker clearly confirmed being that person: "
                        "'yes', 'that's me', 'speaking', or says their own name as that person. 'other_person' if the speaker says they are someone else "
                        "(relative, spouse, colleague), the person is not available, wrong number or the person died. 'unknown' for anything else, "
                        "including 'hello', 'go ahead', 'who is this', 'what is it about'."),
        "min_confidence": 0.6}])

nodes["identity"] = conv(
    "identity", IDENTITY_TASK,
    [verify_tool, transfer_tool(["general"], "Hand the call to a person. CALL it only when the customer insists on a human after you asked once whether you can help. Queue general."),
     close_tool(["transferred", "not_verified"], ["human", "failed", "declined"])],
    [close_route(),
     {"target_node": "load_account", "description": "Identity verified",
      "condition": {"logic": "or", "conditions": [
          {"variable": "verify_identity_response.data.all_verified", "operator": "equals", "operand": "true"},
          {"variable": "verify_identity_response.data.all_verified", "operator": "equals", "operand": "True"}]}}],
    on_enter={"type": "llm", "prompt": "Thank the customer briefly and ask for their date of birth. If they just asked a question, answer it first (without saying why you call). Do not mention the account."},
    first_only=True)

nodes["load_account"] = {
    "name": "load_account", "node_type": "api_request", "passthrough": True,
    "passthrough_default_transition": "prepare", "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True,
    "pre_actions": [{
        "type": "function", "config": {"timeoutMs": 12000, "maxRetries": 2},
        "function": {"name": "get_account", "handler": "__function__:api_call", "description": "Get the late products.",
                     "parameters": {"type": "object", "properties": {
                         "url": {"type": "string", "default": f"{BASE}/get_account"},
                         "method": {"type": "string", "default": "POST"},
                         "headers": HDR,
                         "body": {"type": "object", "properties": {"customer_id": {"type": "string", "default": "{{customer_id}}"}}, "required": []}}}}}],
    "response_mapping": [{"path": "data.products", "variable": "products"}],
    "transitions": [{"target_node": "prepare", "description": "always", "condition": {"operator": "always"}}],
}

nodes["prepare"] = code_node("prepare", PREPARE_CODE, "negotiate", [
    {"target_node": "account_error", "description": "Account could not be loaded",
     "condition": {"logic": "or", "conditions": [{"variable": "acct_state", "operator": "equals", "operand": "error"}]}}])

nodes["negotiate"] = conv(
    "negotiate", NEGOTIATE_TASK,
    [promise_tool, note_tool,
     transfer_tool(["restructuring", "general", "support"],
                   "Hand the call to a person. CALL it with queue restructuring when the customer asks for a new payment plan or lower instalments; support when a customer in hardship accepts the support team; general when the customer insists on a human after you asked once whether you can help."),
     close_tool(ALL_OUTCOMES[:5], ["refused", "hardship", "dispute", "service_error", "restructuring", "human", "support"])],
    [close_route()],
    on_enter={"type": "tts", "text": "{{debt_opening}}"}, first_only=True, turns=80)

nodes["account_error"] = conv(
    "account_error", ACCOUNT_ERROR_TASK, [close_tool(["no_promise"], ["service_error"])], [close_route()],
    on_enter={"type": "llm"}, turns=20)

nodes["hang_up"] = {
    "name": "hang_up", "node_type": "end_call", "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True,
    "transitions": [],
    "terminal": {"type": "function", "function": {"name": "call_closed", "handler": "__function__:end_call",
                 "parameters": {"type": "object", "properties": {"message_mode": {"type": "string", "default": "none"}}}}},
}

wf = {
    "initial_node": "setup",
    "system_prompt": SYSTEM,
    "nodes": nodes,
    "global_nodes": {},
    "test_variables": {"customer_id": "c_test", "first_name": "Daniel", "last_name": "Reyes", "title": "Mr", "now": "2026-10-14T11:00"},
}

for k, n in nodes.items():
    for t in n.get("tools", []):
        for h in ("pre_process_code", "post_process_code"):
            assert "{{" not in t.get(h, "") and "}}" not in t.get(h, ""), (k, h)

json.dump(wf, open(sys.argv[1], "w"), indent=1)
print("ok")

